const PRIOR = [{"file": "SPEC-05-journal.md", "section": "§5 P0.3 — Event emit (acceptance criteria)", "severity": "major", "category": "internal-contradiction / untestable-AC", "summary": "The P0.3 acceptance criterion 'exactly one event is enqueued' contradicts the delivery mechanics the same section cites: with zero registered subscribers (the spec's own v1 state — the event is 'emit-only'), platform/events Publish enqueues one task PER SUBSCRIBER, i.e. zero tasks, so nothing is ever enqueued and the AC is unsatisfiable as written — or, worse, an implementer satisfies it literally by enqueuing the raw `journal:entry_created` task type, which no worker handler consumes (Asynq 'handler not found' error/retry loop).", "evidence": "SPEC-05-journal.md:122-124 AC: 'Given a created entry, then exactly one event is enqueued, after commit (a rolled-back create emits nothing).' vs SPEC-05-journal.md:107-108 'published via `platform/events` (events.md \"Delivery mechanics\")' and :118-119 'The event above is therefore **emit-only**, for future external consumers.' docs/reference/events.md:74-75: '`Publish(ctx, name, payload)` enqueues **one task per subscriber**; the subscription table (event name → consumer task type…) is registered in the wiring layer'; events.md:28 lists `journal:entry_created` consumers as '— emit-only for future external consumers.' Zero subscribers → zero enqueued tasks, so 'exactly one event is enqueued' can never be observed on the queue.", "proposed_fix": "Replace the AC with: '- Given a created entry, then `events.Publish` is called exactly once with `journal:entry_created` and the registered payload, strictly after the create transaction commits (a rolled-back create publishes nothing). With zero registered subscribers at v1 this enqueues no consumer tasks — assert on the Publish call (fake/spy publisher in tests), not on queue contents, and never enqueue the raw event name as a task type (no handler exists; it would error-loop in `cmd/worker`).'"}, {"file": "SPEC-05-journal.md", "section": "Header — Downstream consumers", "severity": "minor", "category": "internal-contradiction", "summary": "The header says SPEC-06's stream projection 'consumes its event', but the spec's own P0.3, SPEC-06 P0.1(a), and the events registry all state the projection is maintained transactionally in-module and `journal:entry_created` is emit-only with no consumers — a stale summary that could lead a reader to wire an event consumer for the projection.", "evidence": "SPEC-05-journal.md:6 '**Downstream consumers:** SPEC-06 (stream projection reads this table and consumes its event)' vs SPEC-05-journal.md:110-111 'the stream projection is maintained transactionally in-module, not through this event (SPEC-06 P0.1)'; SPEC-06-life-stream-home.md:71 '`journal:entry_created` stays emit-only for future external consumers'; docs/reference/events.md:28 consumers column: '— emit-only for future external consumers. The stream projection is maintained **transactionally in-module**'.", "proposed_fix": "Replace line 6 with: '**Downstream consumers:** SPEC-06 (stream projection reads this table; its projection rows are maintained transactionally in this module's service — `journal:entry_created` stays emit-only, see P0.3), SPEC-09 P1.7 (takeout exports it)'."}, {"file": "SPEC-05-journal.md", "section": "§2 Goal 1 / §4 primary user story vs §5 P0.4 and P1.6", "severity": "minor", "category": "ambiguity / P0-P1 scope conflict", "summary": "Goal 1 and the primary user story require capturing 'text + mood' in < 10 s at P0, but the only mood UI is P1.6 (nice-to-have); P0.4 says the composer exposes 'the P1.6 mood slot' without defining whether any working mood input ships at P0. An implementer must guess: ship a freeform mood field at P0 (making P1.6 only the emoji-row upgrade) or ship no mood UI (making the primary user story and Goal 1 unachievable until P1). No P0.4 AC exercises mood, so either reading passes acceptance.", "evidence": "SPEC-05-journal.md:26-27 'captures a journal entry (text + mood) in **< 10 s from `/`**'; :50-51 'I jot \"ăn tối với mẹ, vui\" with a mood in < 10 s … *(primary)*'; :133-134 'The composer exposes an optional **date control** … and the P1.6 mood slot'; :163-164 'P1.6 Mood picker: composer surfaces a preset emoji row + freeform field (schema carries `mood` from P0)'.", "proposed_fix": "In P0.4, replace 'and the P1.6 mood slot' with 'and a minimal freeform `mood` text input (P0 — Goal 1 and the primary user story include mood; P1.6 upgrades this input with the preset emoji row)', and add a P0.4 AC: 'Given a mood entered in the composer, then the created entry stores and renders it.' Alternatively, if mood UI is deliberately P1, reword Goal 1 and the primary user story to drop mood from the P0 capture path."}, {"file": "SPEC-05-journal.md", "section": "§5 P2 — future considerations", "severity": "minor", "category": "wrong-cross-reference", "summary": "P2 attributes 'On-this-day / streaks' to SPEC-06 P1.5, but SPEC-06 P1.5 covers on-this-day memories only — the word 'streak' appears nowhere in SPEC-06 (or brief 06), so the streak read the upstream brief mentioned was dropped downstream and this pointer is wrong for half its claim.", "evidence": "SPEC-05-journal.md:170-171 '**On-this-day / streaks** (SPEC-06 P1.5) read this table by month/day of `occurred_at`' vs SPEC-06-life-stream-home.md:188-192 'P1.5 On-this-day memories: `GET /api/v1/stream/memories` — **journal entries only** … whose `occurred_at` month/day matches today'; `grep -i streak` over SPEC-06 and briefs/06-life-stream-home.md returns no matches.", "proposed_fix": "Change the bullet to: '**On-this-day** (SPEC-06 P1.5) reads this table by month/day of `occurred_at`; a streak widget is a possible later read of the same column (not specced in SPEC-06) — either way, don't denormalize dates away.'"}, {"file": "SPEC-08-people-registry.md", "severity": "major", "category": "internal-contradiction", "section": "§5 P0.2 (birthday wire shape) vs §6 data model", "summary": "P0.2 says `PATCH { birthday: null }` \"clears all four columns\", but §6 declares `birth_calendar text NOT NULL DEFAULT 'solar'` — setting it to NULL is impossible under the schema, so an implementer must either violate the prose or alter the schema.", "evidence": "SPEC-08 §5 P0.2 (lines 82-83): \"`POST`/`PATCH` accept it whole; `PATCH { birthday: null }` clears all four columns\" — vs §6 (line 218): \"birth_calendar  text NOT NULL DEFAULT 'solar' CHECK (birth_calendar IN ('solar','lunar'))\". NULLing birth_calendar violates the NOT NULL constraint; the two resolutions (reset to 'solar' vs drop NOT NULL) diverge at the schema level.", "proposed_fix": "In P0.2 replace \"`PATCH { birthday: null }` clears all four columns\" with: \"`PATCH { birthday: null }` NULLs `birth_month`/`birth_day`/`birth_year` and resets `birth_calendar` to its `'solar'` default (the column is NOT NULL per §6)\". Keep §6 unchanged."}, {"file": "SPEC-08-people-registry.md", "severity": "minor", "category": "ambiguity", "section": "§5 P0.2 (birthday edit / notice reset) vs SPEC-06 consumers", "summary": "The birthday-edit rule deletes current/future-year `people_birthday_notices` rows to fix the stale-dedup bug, but says nothing about already-emitted downstream items keyed on those `notice_id`s — stale stream/bell cards for the old (wrong) date persist, and their `notice_id` refs now dangle (the notice row is deleted while SPEC-06 keys `ref_id = notice_id` on it).", "evidence": "SPEC-08 §5 P0.2 (lines 85-88): \"Editing or clearing a birthday also deletes the person's `people_birthday_notices` rows for the current and future occurrence years\" — no retraction or accepted-staleness statement. SPEC-06-life-stream-home.md:90: \"`people:birthday_upcoming` | SPEC-08 P0.4 | **`notice_id`** (in the payload — SPEC-08 §6) | insert\", i.e. stream items already inserted from the pre-edit notice survive the notice-row deletion.", "proposed_fix": "Add one sentence to the P0.2 birthday-wire-shape paragraph, e.g.: \"Already-emitted stream/notification items from the deleted notices are NOT retracted at v1 — accepted staleness (they age out; the corrected date emits fresh events under new notice_ids). Consumers must therefore not re-fetch by notice_id (the row may be gone); the payload is self-sufficient for rendering.\" (Or, if retraction is wanted, define a `people:birthday_notice_revoked` event — but pick one explicitly.)"}, {"file": "SPEC-08-people-registry.md", "severity": "minor", "category": "missing-api-field", "section": "§5 P1.7 vs §7 API summary", "summary": "P1.7 introduces settable `avatar_asset_id` (with problem type `people/invalid-asset`), but no endpoint in §7 carries the field — the POST body is enumerated without it and the PATCH row only mentions birthday semantics, so how the client sets/clears an avatar is unspecified.", "evidence": "SPEC-08 §7 line 263: POST body \"`{display_name, relationship?, birthday?, contact?, note_md?}`\" — no `avatar_asset_id`; §7 line 266 (PATCH): \"`birthday: null` clears; birthday edits reset current/future notice rows (P0.2)\" — no avatar mention; yet §7 lines 271-272 declare \"`people/invalid-asset` (P1.7)\" and §5 P1.7 (lines 195-196) requires \"`avatar_asset_id` via `mediaapi` (ready image, owner — SPEC-01)\".", "proposed_fix": "In §7, extend the PATCH row's Notes with: \"P1.7 adds `avatar_asset_id?: uuid|null` (validated via `mediaapi`: asset exists, kind image, status ready, owned by caller — else 422 `people/invalid-asset`; `null` clears)\", and note in P1.7 that the field lands on PATCH (and optionally POST) when P1.7 ships."}, {"file": "SPEC-09-platform-ops.md", "severity": "major", "section": "§5 P0.2 vs §5 P0.4 vs §9", "category": "internal-contradiction / missing AC", "summary": "P0.4 requires that \"P0.2's task overwrites backups/pg/LATEST.json {storage_key, sha256, size_bytes, finished_at}\" after every successful run, but P0.2's 5-step mechanics, its acceptance criteria, and timeline step 2 all omit the manifest write and the sha256 computation — an implementer building P0.2 (timeline step 2) from its own section ships a backup task the restore drill (step 3) cannot use.", "evidence": "P0.4 step 1 (SPEC-09:115-118): \"Selection via manifest: after every successful run, P0.2's task overwrites a small `backups/pg/LATEST.json` `{storage_key, sha256, size_bytes, finished_at}`\" — but P0.2's mechanics (SPEC-09:78-89) list only insert-row / pg_dump-stream / finish-row / retention / events, its ACs (SPEC-09:90-96) never mention the manifest or sha256, and §9 step 2 (SPEC-09:262) reads \"Backup task + streaming + retention + events + audit\". The sha256 also constrains implementation: the dump is streamed straight into storage (§10 resolved, SPEC-09:276-279), so the hash must be computed by teeing the stream — nothing in P0.2 says so, and `ops_backup_runs` (§6, SPEC-09:205-214) has no sha256 column to fall back on.", "proposed_fix": "In P0.2, insert a new step between current steps 3 and 4: \"3b. On success, overwrite `backups/pg/LATEST.json` `{storage_key, sha256, size_bytes, finished_at}` — the sha256 is computed by teeing the pg_dump stream through a hasher during upload (the dump is never on disk). The manifest is what P0.4's drill trusts; retention (step 4) must never delete it or the object it points to.\" Add an AC: \"Given a successful run, then LATEST.json points at the new dump and its sha256 matches the stored object.\" Update §9 step 2 to \"Backup task + streaming + manifest + retention + events + audit\"."}, {"file": "SPEC-09-platform-ops.md", "severity": "minor", "section": "§5 P0.5 acceptance criteria", "category": "AC contradicts behavior spec", "summary": "The stale AC (\"Given last success 27 h ago, then state=stale\") contradicts the spec's own precedence rule 1 in the world where a run failed after that success — precedence says `failed` wins; and the two newly-resolved semantics (failed-wins precedence, never-ran ⇒ stale) have no AC at all.", "evidence": "SPEC-09:147-148: \"1. `failed` — the most recent completed run has `status='failed'` … wins even if an older success is < 26 h old\" vs SPEC-09:162: \"Given last success 27 h ago, then `state=stale`\" — if the reason the last success is 27 h old is a failed run since, the correct state is `failed`, so the AC as written is false for some inputs satisfying its Given. The precedence and zero-runs semantics were added precisely because they \"were undefined\" (SPEC-09:143-144), yet neither is exercised by an AC.", "proposed_fix": "Rewrite the AC block as: \"- Given last success 27 h ago **and no completed run since**, then `state=stale`; given a fresh success, `ok`.\\n- Given a success 2 h ago followed by a failed run, then `state=failed` (precedence).\\n- Given zero runs ever, then `state=stale` with `last_success_at: null`, `hours_since_success: null`.\\n- Given a non-admin caller, then 403; unauthenticated, 401.\""}, {"file": "SPEC-09-platform-ops.md", "severity": "minor", "section": "§5 P1.7 / §7 API summary", "category": "undefined behavior", "summary": "Problem type `ops/export-not-ready` is declared in §7 but no behavior in P1.7 ever triggers it — P1.7 says GET returns status (any state) and 410 `ops/export-expired` for expired, leaving an implementer to guess when not-ready fires.", "evidence": "SPEC-09:243-244 lists \"Problem types: `ops/export-not-found`, `ops/export-not-ready`, `ops/export-expired`\", but P1.7 (SPEC-09:181-183) defines GET as \"returns status + a short-TTL download URL\" and only specifies \"`GET` on an expired export returns 410 Problem `ops/export-expired`\". No state maps to `ops/export-not-ready`.", "proposed_fix": "Either delete `ops/export-not-ready` from §7, or define its trigger in P1.7, e.g.: \"GET on a `pending`/`running`/`failed` export returns 200 with the status and no `download_url`; `ops/export-not-ready` is reserved for a client explicitly requesting the download URL of a non-`ready` export (409)\" — pick one and state it."}, {"file": "SPEC-09-platform-ops.md", "severity": "minor", "section": "Header / §1 vs §5 P0.2", "category": "dependency contradiction", "summary": "The spec markets itself as dependency-free (\"Depends on: nothing hard\", \"dependency-free burst-filler\"), but P0.2 mandates running on \"the shared periodic runner (SPEC-01 P0.3's convention)\" — infrastructure SPEC-04 explicitly says SPEC-01 P0.3 introduces; if SPEC-09 lands before SPEC-01 (which its own sequencing pressure argues for, ahead of SPEC-03), the runner does not exist.", "evidence": "SPEC-09:4 \"Depends on: nothing hard\" and SPEC-09:22-24 \"dependency-free burst-filler\" vs SPEC-09:72 \"On the shared periodic runner (SPEC-01 P0.3's convention — no OS cron)\"; SPEC-04-notification-module.md:159 confirms it is \"the same periodic-runner infrastructure SPEC-01 P0.3's `media:purge_orphans` **introduces**\". SPEC-09 §1 (lines 21-24) simultaneously argues P0 should land before SPEC-03, which in the README order (specs/README.md:81-83) precedes SPEC-09's slot.", "proposed_fix": "Add one sentence to P0.2: \"If this spec lands before SPEC-01 P0.3, `ops` introduces the shared Asynq periodic scheduler itself (a few lines in `cmd/worker`) — what is borrowed from SPEC-01 is the convention (Asynq periodic tasks, never OS cron), not code.\""}, {"file": "SPEC-09-platform-ops.md", "severity": "minor", "section": "§5 P0.5 / P1.6 / P1.7 vs §6", "category": "ambiguous requirement", "summary": "\"This phase's migration\" is ambiguous for the P1 permission seeds: P1.6 says `queues:read` is seeded \"in this phase's migration, alongside `ops:read`\" — but `ops:read` is seeded by the P0 migration (P0.5), while §6 says the P1.7 table \"may ship in a later migration with that phase\"; an implementer cannot tell whether the four permission rows go in `000N_ops_backup_runs` or a later P1 migration (the README seeding rule requires the introducing migration to be named).", "evidence": "SPEC-09:139-140: \"the ops migration seeds it [`ops:read`] and grants to `admin`\"; SPEC-09:166-169: \"`queues:read` (seeded and granted to `admin` in this phase's migration, alongside `ops:read`…)\"; SPEC-09:174-176: \"`takeout:write:own` … seeded to `user` with `takeout:read:own` in this phase's migration\"; §6 SPEC-09:217: \"-- P1.7 (may ship in a later migration with that phase)\". specs/README.md:56-60 (seeding rule) requires the seed rows to ship \"in its own migration\".", "proposed_fix": "State explicitly which migration carries which seeds, e.g. in P0.1: \"Migration `000N_ops_backup_runs` also seeds all four permission rows up front — `ops:read`, `queues:read` → `admin`; `takeout:read:own`, `takeout:write:own` → `user` (unseeded codes 403; seeding early is harmless). The `ops_exports` table may still ship in a later P1 migration.\" Then drop the per-requirement \"this phase's migration\" phrasing."}, {"file": "SPEC-09-platform-ops.md", "severity": "minor", "section": "§8 vs §5 P0.5", "category": "stale naming", "summary": "§8 refers to the status field as `hours_since`, but the P0.5 response schema names it `hours_since_success`.", "evidence": "SPEC-09:253: \"`hours_since` never exceeds 26 outside induced failures\" vs SPEC-09:142: \"Returns `{last_success_at, hours_since_success, state, last_run: {...}}`\".", "proposed_fix": "In §8, replace \"`hours_since`\" with \"`hours_since_success`\"."}, {"file": "SPEC-07-continue-rail.md", "severity": "major", "section": "§5 P0.4 / §7 API summary / §5 P0.3", "category": "unimplementable-requirement", "summary": "There is no read path for the saved position: P0.4 requires Vidstack to start at the saved position and P0.2's AC requires resume on direct asset reopen, but the API surface exposes only a write (PUT progress) and /continue items that carry progress_pct without position_ms.", "evidence": "P0.4 (line 122-124): \"Vidstack starts at the saved position when one exists\"; P0.2 AC (line 86-88): \"Given playback to 12:34 then tab close, when the asset is reopened, then the player offers resume at ~12:34 (±10 s)\". Yet §7 (lines 169-172) lists only `PUT /api/v1/assets/{id}/progress` and `GET /api/v1/continue`, and the P0.3 item shape (line 103) is `[{module, ref_id, title, poster_url, progress_pct, href, updated_at}]` — no `position_ms`. A user reopening an asset directly (not via the rail) has no source for the position at all, and even via the rail a rounded percentage cannot reconstruct ±10 s on long videos. Note the spec's own ref, feature-inventory D-20 (feature-inventory.md:1224-1232), gave `ContinuingItem` explicit `Position` and `Duration` fields that this spec silently dropped — also relevant: NULL-duration assets are excluded from /continue (P0.1, line 62) but P0.1 (line 61-62) promises \"resume still works from the saved position\" for them, so /continue cannot be the read path even in principle.", "proposed_fix": "Add a read endpoint and field. (1) In §7, add row: `| GET | /api/v1/assets/{id}/progress | authenticated (RequireAuth; owner-scoped — P0.2) | returns {position_ms, progress_pct (null when duration_ms IS NULL), completed_at, updated_at}; 404 semantics identical to the PUT (unknown, non-video, deleting, not owned); 404 media/asset-not-found when no progress row exists |`. (2) In P0.4, state the player fetches this endpoint (or receives the progress object embedded in the existing asset-detail/playback response — pick one and say so) before initializing Vidstack. (3) Optionally add `position_ms` to the P0.3 item shape, and note the deliberate divergence from D-20's ContinuingItem (Position/Duration → progress_pct) next to the D-20 ref in the header."}, {"file": "SPEC-07-continue-rail.md", "severity": "major", "section": "§5 P0.1 vs P0.4", "category": "internal-contradiction", "summary": "P0.1's NULL-duration rule promises \"resume still works from the saved position\", but P0.4 gates resume on \"below 95%\" — a condition that is undefined for NULL-duration assets, so the two P0 requirements contradict each other for exactly the edge case the spec itself raises.", "evidence": "P0.1 (lines 58-64): \"for an asset with `duration_ms IS NULL` ... resume still works from the saved position, but `progress_pct` is undefined\". P0.4 (lines 122-124): \"Vidstack starts at the saved position when one exists above the 30 s threshold and below 95%, ... otherwise starts at 0.\" With progress_pct undefined, \"below 95%\" cannot be evaluated, so a literal reading of P0.4 starts NULL-duration assets at 0 — contradicting P0.1.", "proposed_fix": "Amend P0.4's first sentence to: \"Vidstack starts at the saved position when one exists above the 30 s threshold and below 95% — the percent gate is skipped when `progress_pct` is undefined (NULL `duration_ms`, P0.1), in which case any saved position ≥ 30 s resumes — with a visible 'Start over' affordance; otherwise starts at 0.\""}, {"file": "SPEC-07-continue-rail.md", "severity": "major", "section": "Header (Depends on) / §5 P0.2, P0.3 / §7", "category": "wrong-dependency", "summary": "The header claims \"Depends on: nothing hard (the video leg runs on today's stack)\", but three P0 ingredients only exist once SPEC-01 P0 ships: the asset `title` (used in the /continue item shape), the `deleting` status (P0.2 404s on it), and the `media/asset-not-found` problem type that §7 marks \"(reused)\".", "evidence": "SPEC-07 line 4: \"Depends on: nothing hard (the video leg runs on today's stack)\". But migration 0007 (backend/db/migrations/0007_media_assets.up.sql:11-27) has no `title` column and its CHECK allows only `('uploading','processing','ready','failed')` — `deleting` is added by SPEC-01 (SPEC-01-media-image-pipeline.md:311: \"CHECK (status IN ('uploading','processing','ready','failed','deleting'))\", and :317: \"`'deleting'` is required by P0.3. `title` / `original_filename` are required by...\"). `media/asset-not-found` appears only in SPEC-01's problem-type list (SPEC-01:340), not in shipped code (grep of backend/*.go finds neither the type URI nor any `title` field in the media module). Yet SPEC-07 P0.3's item shape (line 103) requires `title`, P0.2 (line 76-77) 404s `deleting` assets, and §7 (line 174) says \"`media/asset-not-found` (reused)\".", "proposed_fix": "Either (a) change the header to \"Depends on: SPEC-01 P0 (soft — supplies `assets.title`, the `deleting` status, and the `media/asset-not-found` problem type); the beacon/resume leg runs on today's stack\", or (b) keep the no-dependency claim and define fallbacks explicitly in P0.2/P0.3: `title` falls back to the source filename derived from `source_key` until SPEC-01 lands; the `deleting` check is a no-op until the status exists; §7 changes \"(reused)\" to \"(shared with SPEC-01 — first spec to ship defines it)\"."}, {"file": "SPEC-07-continue-rail.md", "severity": "minor", "section": "§5 P0.1", "category": "missing-acceptance-criteria", "summary": "The P0.1 NULL-duration rule — a P0 behavior the spec added deliberately (excluded from /continue, no completion event, resume still works) — has no acceptance criterion anywhere; P0.2/P0.3/P0.4 ACs all assume a known duration.", "evidence": "P0.1 (lines 58-64) defines beacon-upsert/resume/exclusion/never-emit behavior for `duration_ms IS NULL`, but the AC lists at lines 85-90, 115-119, and 126-129 contain no NULL-duration case (e.g. P0.3's AC only covers \"items at 20 s watched and at 97% watched\").", "proposed_fix": "Add to P0.3's acceptance criteria: \"Given a saved position of 10:00 on an asset with `duration_ms IS NULL`, then the item does not appear in `/continue`, reopening the asset still offers resume at ~10:00, and no `media:playback_completed` event is ever emitted for it.\""}, {"file": "SPEC-07-continue-rail.md", "severity": "minor", "section": "§5 P0.2 acceptance criteria", "category": "stale-reference", "summary": "The AC qualifier \"(no wildcard perms)\" is a leftover from the dropped `media:progress:own` permission design — with authorization now \"RequireAuth + owner-scoped by construction\", no permission (wildcard or otherwise) is consulted, so the parenthetical implies a superadmin bypass path the spec no longer defines.", "evidence": "P0.2 AC (line 88): \"Given a beacon for another user's asset (no wildcard perms), then 404 and no row.\" But P0.2 prose (lines 68-73) says the endpoint is \"authenticated (`RequireAuth`), owner-scoped by construction\" and that the drafted `media:progress:own` code was \"dropped for parity with the existing progress convention\" — there is no permission check for a wildcard grant to bypass.", "proposed_fix": "Replace the AC with: \"Given a beacon for another user's asset (regardless of the caller's role or permission grants — there is no permission-based bypass), then 404 and no row.\""}, {"category": "security / contradiction", "file": "SPEC-02-comic-vertical.md", "section": "§5 P0.2 + §7 API summary", "severity": "critical", "summary": "Owner-scoped write endpoints are specified as enforced 'all via RequirePermission' with `comics:write:own`, which neither checks ownership nor admits the seeded `comics:write:any`/`comics:delete:any` moderation grants — as written, any creator can modify any other creator's comic, and admin moderation is impossible.", "evidence": "SPEC-02:81 \"Permissions (all via `RequirePermission`; wildcard `comics:*` covers every scope)\"; SPEC-02:98-99 seeds \"`comics:delete:any` + `comics:write:any` → admin-tier for moderation\" yet no §7 endpoint requires either code — §7:309/310 list PATCH/DELETE `/api/v1/comics/{id}` as `comics:write:own` only. backend/internal/modules/account/rbac/permission.go:15-16: \"require (\\\"movies:write:any\\\") only when the third segment is \\\"any\\\". Owners must be explicitly granted \\\":own\\\" and check ownership at call site\"; permission.go:111: \"granted(\\\"movies:write:own\\\") satisfies movies:write:own ONLY\" and an `:any` grant satisfies bare/`:any`, never `:own`. So RequirePermission(comics:write:own) (a) passes any user holding the grant regardless of who owns the comic, and (b) rejects an admin holding only the `:any` codes.", "proposed_fix": "In P0.2, replace the enforcement sentence with: \"Reads via RequirePermission. All owner-scoped writes (PATCH/DELETE comic, chapter and page mutations, publish) go through `RequireOwnerOrPermission`: caller must own the comic AND hold `comics:write:own` (publish: `comics:publish:own`), OR hold the moderation grant `comics:write:any` (`comics:delete:any` for DELETE). Ownership comparison is the service's responsibility — `:own` in the grant does not check it.\" Update the §7 Permission column on every write row accordingly (e.g. `owner + comics:write:own | comics:write:any`). Add two ACs: \"Given creator D (holds comics:write:own) and creator C's comic, when D PATCHes/DELETEs it, then 404/403 and no change\" and \"Given an admin holding comics:write:any (no wildcard), when they PATCH another user's comic, then 200 (moderation path works)\"."}, {"category": "internal contradiction / impossible requirement", "file": "SPEC-02-comic-vertical.md", "section": "§5 P1.7 Zip chapter upload", "severity": "major", "summary": "The import task's ~10-minute poll timeout is arithmetically incompatible with the spec's own 300-entry ceiling given SPEC-01's heavy-queue concurrency 1–2 and <10 s-per-image budget — a maximum-size legal zip systematically times out and reports failures for assets that would have reached ready.", "evidence": "SPEC-02:218-219 \"polls their status via `mediaapi` (~2 s interval, bounded timeout ≈ 10 min)\" and :221 \"max 300 entries\"; SPEC-01:122 heavy server \"Concurrency: 1–2\" and SPEC-01 §2 goal 1 \"reaches `ready` ... in < 10 s for a 12 MP JPEG\" — 300 images × up to 10 s ÷ concurrency 1 ≈ 50 min ≫ 10 min. SPEC-02:222-223 then treats poll timeouts as per-file failures: \"Failures (including poll timeouts) produce a per-file report\".", "proposed_fix": "Replace \"bounded timeout ≈ 10 min\" with a bound derived from the batch: \"bounded timeout = max(10 min, entry_count × 15 s ÷ heavy-queue concurrency) — sized so a full 300-entry import at concurrency 1 (SPEC-01 P0.1) cannot time out while its assets are still queued; only assets individually stuck > that window are reported as failures.\""}, {"category": "missing API surface", "file": "SPEC-02-comic-vertical.md", "section": "§7 API summary vs §4/§5 P0.1", "severity": "major", "summary": "Page deletion is required by a user story and exercised by a P0.1 acceptance criterion, but §7 defines no endpoint to delete (or update) a page — an implementer must invent path, method, and permission.", "evidence": "SPEC-02:47-48 user story \"I reorder or remove pages before publishing\"; SPEC-02:74-75 AC \"Given pages inserted with sort_order 10,20,30, when 20 is deleted, then reader order is stable\"; §7 (lines 303-318) contains only POST `/chapters/{id}/pages`, PUT `pages:order`, and GET `pages` — no DELETE for a page anywhere in the table.", "proposed_fix": "Add a row to §7: `| DELETE | /api/v1/pages/{id} | owner + comics:write:own (moderation: comics:delete:any) | removes the page row only; the media asset is untouched (P0.1) |` and mention the endpoint in P0.1's prose."}, {"category": "acceptance-criteria gap", "file": "SPEC-02-comic-vertical.md", "section": "§5 P0.5 Library + detail pages", "severity": "major", "summary": "P0.5 is the only P0 requirement with no acceptance criteria at all — there is no testable definition of done for the library grid, the My-comics tab, pagination, or the placeholder replacement.", "evidence": "SPEC-02:165-171 (P0.5) ends at the description; every other P0 section (P0.1:66, P0.2:105, P0.3:123, P0.4:147, P0.6:194) has an explicit \"**Acceptance criteria.**\" block — P0.5 has none.", "proposed_fix": "Add to P0.5: \"**Acceptance criteria.** — Given a published and a draft comic by another creator, when a reader opens /library/comic, then only the published one appears (cover = thumb variant, title, chapter count, updated date). — Given the creator, then the My comics tab lists both with status badges; a reader never sees the tab's drafts. — Given > 1 page of comics, then pagination loads the next page without duplicates. — The pre-existing placeholder component is gone from the route (regression). — Detail page shows the Continue button iff progress exists (P0.4).\""}, {"category": "ambiguous requirement", "file": "SPEC-02-comic-vertical.md", "section": "§5 P1.7 / §7 pages:import-zip", "severity": "major", "summary": "The spec never defines how the up-to-500 MB zip reaches the worker: the only ingest path in the platform is SPEC-01's presigned browser→bucket PUT capped at 50 MB, and events.md's task payload references an `upload_ref` the spec never mentions or defines.", "evidence": "SPEC-02:207 \"`POST /api/v1/chapters/{id}/pages:import-zip` — one .zip of images → worker task `comic:import_zip` unpacks\" and :220-221 \"max 500 MB zip\" — no transport specified; docs/reference/events.md:41 defines the task payload as `{chapter_id, upload_ref}` (`upload_ref` undefined anywhere in SPEC-02); SPEC-01:89-91 the existing flow enforces \"The 50 MB cap ... `content-length-range` condition on the presigned PUT policy\".", "proposed_fix": "Specify the transport in P1.7, e.g.: \"The zip is uploaded via a dedicated presigned PUT (separate import prefix, 500 MB `content-length-range`, never creating an `assets` row); the client then POSTs pages:import-zip `{upload_ref: <storage key>}`, which enqueues `comic:import_zip {chapter_id, upload_ref}` (payload per events.md). The worker streams the object from storage and deletes it after processing.\" Add the request body to the §7 row's Notes."}, {"category": "missing data-model/API surface", "file": "SPEC-02-comic-vertical.md", "section": "§5 P1.6 / P1.8 vs §6/§7", "severity": "minor", "summary": "P1.6's server-side reader-mode preference and P1.8's bookmarks have no storage (no table/column in §6) and no endpoint (absent from §7, unlike fellow P1 item zip-import which got a §7 row and a Problem type) — both are unbuildable as written.", "evidence": "SPEC-02:205-207 \"mode persisted per user — server-side pref, for cross-device continuity\" and :224 \"P1.8 Bookmarks: per user, per page; list on the detail page\"; §6 (lines 236-275) defines only comics/comic_chapters/comic_pages/comic_reading_progress; §7 (303-318) lists pages:import-zip (P1.7) but no pref or bookmark endpoint.", "proposed_fix": "Either add the surfaces — §6: `comic_bookmarks(user_id, page_id fk ON DELETE CASCADE, created_at, pk(user_id, page_id))` plus a `reader_mode` column on a per-user pref row (or extend comic_reading_progress with `reader_mode text`); §7: `GET/PUT /api/v1/comics/reader-prefs` (authenticated) and `PUT/DELETE /api/v1/pages/{id}/bookmark` + `GET /api/v1/comics/{id}/bookmarks` (authenticated, readable-comic rule as P0.4) — or append to both P1 items: \"schema + endpoints to be added to §6/§7 when this P1 is scheduled\"."}, {"file": "MULTIPLE", "severity": "major", "category": "internal-contradiction", "section": "README §Conventions binding on all specs — AuthZ bullet vs SPEC-04 §5/§7 permission codes", "summary": "The README's canonical action set (`read | write | delete` plus sparing domain verbs like `publish`), which it claims 'reconciles the drafts', is contradicted by SPEC-04's live permission codes that use `update` and `create` — an implementer must guess whether to seed `notifications:update:own` (per SPEC-04's tables and seeding block) or `notifications:write:own` (per the binding README convention that SPEC-03 already follows).", "evidence": "specs/README.md:52-54: \"action ∈ `read | write | delete` plus sparing domain verbs (`publish`)\" and README.md:51 \"(reconciles the drafts; matches the 0003 seed catalog...)\". Conflicting: SPEC-04-notification-module.md:69-72 seeds \"`notifications:update:own`, `notification-prefs:read:own`, `notification-prefs:update:own`, `push-subscriptions:create:own`, `push-subscriptions:delete:own`\" and its §7 API table (lines 210-213) requires `notifications:update:own`, `notification-prefs:read/update:own`, `push-subscriptions:create/delete:own`. Meanwhile SPEC-03-finance-ledger.md:303-310 explicitly follows the README rule: \"actions follow the 0003 catalog's `read|write|delete`... `write` covers create + update\" — so the two specs establish two different verb conventions under a README that claims they are reconciled. (0003_account_rbac.up.sql's own catalog uses `write` for create+edit, e.g. 'assets:write:own' — \"Upload + edit own assets\".)", "proposed_fix": "Pick one verb set and make both documents agree. Preferred (matches 0003 and SPEC-03): in SPEC-04, rename `notifications:update:own` → `notifications:write:own`, `notification-prefs:update:own` → `notification-prefs:write:own`, `push-subscriptions:create:own` → `push-subscriptions:write:own` in the §5 seeding block and both API tables (§5 P0.5 and §7), keeping `push-subscriptions:delete:own`. Alternatively, if `update`/`create` are to be kept, amend the README bullet to read: \"action ∈ `read | write | delete` (write covers create+update — 0003 precedent) plus sparing domain verbs (`publish`); SPEC-04's `update`/`create` codes are grandfathered and must not be copied\" — but do not leave the README claiming the drafts are reconciled while SPEC-04's codes violate the stated set."}, {"file": "README.md", "severity": "minor", "category": "wrong-cross-reference", "section": "§Conventions binding on all specs — AuthZ bullet", "summary": "The claim that the canonical naming scheme 'matches the 0003 seed catalog' is factually wrong for a third of that catalog: 0003 seeds several codes whose third segment is not a scope and whose actions fall outside `read|write|delete|publish`, so an implementer told the catalog matches may copy those shapes.", "evidence": "specs/README.md:51-55: \"(reconciles the drafts; matches the 0003 seed catalog and `rbac/permission.go`'s own examples)... action ∈ `read | write | delete` plus sparing domain verbs (`publish`); scope ∈ `own | any` **only**\". Conflicting rows in backend/db/migrations/0003_account_rbac.up.sql:101-119: `('moderation:flag', ...)`, `('moderation:hide', ...)`, `('moderation:ban_user', ...)`, `('rbac:role:read', ...)`, `('rbac:role:write', ...)`, `('rbac:role:assign', ...)`, `('system:settings:write', ...)` — `rbac:role:read` and `system:settings:write` put an action verb in the scope slot (violating scope ∈ own|any), and `flag`/`hide`/`ban_user`/`assign` are actions outside the README's stated set.", "proposed_fix": "Qualify the parenthetical, e.g.: \"(reconciles the drafts; matches `rbac/permission.go`'s own examples and the 0003 catalog's domain rows (`assets:*`, `movies:*`, ...) — 0003's admin-plane codes (`rbac:role:*`, `system:settings:write`, `moderation:*`) predate this scheme and are grandfathered literal codes: they match only their own literal grants and must not be used as templates for new modules)\"."}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "major", "category": "missing-api-surface", "section": "§5 P0.1/P0.3/P0.4/P0.5, §7 API summary", "summary": "The spec requires image variants (thumb/medium/poster) to be rendered, referenced by URL, and 404-checked, but never defines how a variant is served — no endpoint, URL scheme, or auth stance exists anywhere in §5 or §7.", "evidence": "P0.3 AC (SPEC-01:194-195): \"its HLS URL, variant URLs, and original-download URL return 404/403\"; P0.5 (SPEC-01:233-235): \"the original must never be reachable through the public-ish variant/HLS URL scheme\" — presupposing a variant URL scheme that is defined nowhere; P0.4 AC (SPEC-01:222): \"thumb variants only — never originals in the grid\". §7 table (SPEC-01:327-332) lists only DELETE /assets/{id}, GET /assets/{id}/original, PATCH /assets/{id}, GET /assets. Shipped code serves only HLS: backend/internal/modules/media/module.go:68 `r.Get(\"/{id}/hls/*\", m.handler.HLS) // public playback` — there is no existing variant route to extend.", "proposed_fix": "Add a variant-serving endpoint to §5 P0.1 and the §7 table, e.g. `GET /api/v1/assets/{id}/variants/{variant}` (variant ∈ thumb|medium|poster) — streamed with the variant's content type, cache headers, and the same \"public-ish\" auth stance as `/assets/{id}/hls/*` (explicitly state whether it is unauthenticated like HLS or requires `assets:read:own`), returning 404 `media/asset-not-found` for missing/deleted assets. Add the row to §7 so it lands in shared/openapi.yaml per specs/README.md conventions."}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "major", "category": "internal-contradiction", "section": "§5 P0.5 acceptance criteria vs §5 P0.1 behavior", "summary": "P0.5's AC guarantees the original of any `failed` asset is downloadable, but P0.1's file-too-large path deletes the source object while setting the asset `failed` — for those assets the guaranteed download is impossible.", "evidence": "P0.5 AC (SPEC-01:245-247): \"Given an asset in `processing`/`failed`, the original is still downloadable (upload succeeded even if derivation didn't) — Problem `media/asset-not-found` only for missing/deleted assets.\" vs P0.1 (SPEC-01:91-93): \"re-checked via HEAD at `/complete` (on violation: object deleted, asset `failed`, Problem `media/file-too-large`)\" and P0.1 AC (SPEC-01:144-146): \"the object is deleted from storage, and the asset is `failed`\".", "proposed_fix": "Amend the P0.5 AC to: \"Given an asset in `processing`/`failed` whose source object still exists (worker-side failure: corrupt, animated, oversized-dimensions), the original is still downloadable. Given an asset rejected at `/complete` with its object purged (file-too-large, unsupported-format), then 404 Problem `media/asset-not-found` — the archival guarantee applies only to accepted uploads.\""}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "major", "category": "undefined-behavior", "section": "§5 P0.1 — HEIC/unsupported-format rejection at /complete", "summary": "The HEIC/unsupported-format rejection at `/complete` defines only the 422 response; the fate of the asset row and the already-uploaded storage object is unspecified — as written the asset stays `uploading` forever, which (per the rev-3 filter rule) shows it under the `processing` filter indefinitely.", "evidence": "SPEC-01:88-89: \"HEIC/HEIF magic bytes are recognized specifically and rejected with a convert-on-device hint\" and AC SPEC-01:136-138: \"Given a HEIC upload, when sniffed at `/complete`, then 422 Problem `media/unsupported-format`...\" — no status transition or object cleanup is stated, unlike the too-large path (SPEC-01:91-93: \"object deleted, asset `failed`\"). P0.4 (SPEC-01:210-212): \"the `processing` filter includes still-`uploading` sessions\" means such an asset is permanently listed as processing.", "proposed_fix": "Add to P0.1 behavior: \"On unsupported-format detection at `/complete` (HEIC or any non-JPEG/PNG/WebP magic bytes): return 422 Problem `media/unsupported-format`, delete the uploaded object, and set `status='failed'` with an `error_message` naming the detected format (HEIC gets the convert-to-JPEG hint) — mirroring the file-too-large handling.\" Add a matching clause to the HEIC AC (\"...and the asset is `failed` with the HEIC-specific error_message; the object is removed from storage\")."}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "minor", "category": "missing-lifecycle", "section": "§5 P0.3 janitor / P0.5", "summary": "The spec acknowledges abandoned `uploading` sessions (P0.5 AC) but defines no cleanup for them — the janitor sweeps only `status='deleting'`, so abandoned rows and partial objects accumulate forever, against Goal 3's storage-reclamation intent.", "evidence": "SPEC-01:185-187: janitor \"selects assets WHERE status='deleting' AND updated_at < now() - interval '15 minutes'\" — nothing sweeps `uploading`; SPEC-01:247-249: \"Given an asset still `uploading` (browser PUT unfinished or abandoned)\" explicitly names the abandoned case; Goal 3 (SPEC-01:27-28): \"DB rows and all storage objects are gone afterwards\".", "proposed_fix": "Extend `media:purge_orphans` in P0.3: also select `WHERE status='uploading' AND updated_at < now() - interval '24 hours'`, mark those `failed` (error_message 'upload abandoned') or transition them to `deleting` for purge — or add an explicit non-goal/open-question entry deferring abandoned-upload cleanup with rationale."}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "minor", "category": "missing-field-semantics", "section": "§5 P0.5 / §6", "summary": "`Content-Disposition: attachment; filename=\"<original filename>\"` is undefined for every asset uploaded before the §6 migration — `original_filename` is null for all pre-existing rows and no fallback is specified.", "evidence": "SPEC-01:232-233: \"Streams the source object with Content-Disposition: attachment; filename=\\\"<original filename>\\\"\"; SPEC-01:319-321: \"the shipped table stores neither... The upload-session endpoint starts recording `original_filename`\" — i.e. only new uploads get it.", "proposed_fix": "Add to P0.5 behavior: \"When `original_filename` is null (assets predating the migration), fall back to `{asset_id}.{ext}` where ext is derived from the sniffed content type (or the `source_key` extension).\""}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "minor", "category": "incomplete-api-contract", "section": "§7 API summary", "summary": "§7 omits the modified `POST /api/v1/assets/{id}/complete` contract even though P0.1 substantially changes it (magic-byte sniffing, HEAD size re-check, new 422 `media/unsupported-format` and `media/file-too-large` responses) — the specs/README convention requires every endpoint change to land in shared/openapi.yaml.", "evidence": "§7 table (SPEC-01:327-332) lists only DELETE/GET-original/PATCH/GET-list; P0.1 (SPEC-01:86-93) changes `/complete` behavior and error surface. specs/README.md:62-63: \"every endpoint added here must land in `shared/openapi.yaml`\".", "proposed_fix": "Add a row to the §7 table: `| POST | /api/v1/assets/{id}/complete | (existing auth) | extended: magic-byte sniff + HEAD size re-check; new Problems media/unsupported-format (422), media/file-too-large |` so the OpenAPI response set is updated alongside the new endpoints."}, {"file": "SPEC-04-notification-module.md", "severity": "major", "category": "convention-contradiction", "section": "§5 P0.1 permission seeding + §7 API summary", "summary": "Permission action verbs `update` and `create` violate the specs README's binding canonical action set (read | write | delete), which SPEC-04 §7 itself cites as the reconciled scheme.", "evidence": "SPEC-04:56-57 and 210-213 use `notifications:update:own`, `notification-prefs:read/update:own`, `push-subscriptions:create/delete:own`; SPEC-04:220 claims the codes follow \"the canonical scheme in the specs README's AuthZ convention\". README.md:53 binds: \"action ∈ `read | write | delete` plus sparing domain verbs (`publish`)\". The shipped 0003 catalog (backend/db/migrations/0003_account_rbac.up.sql:79-112) contains only read/write/delete actions, and SPEC-01 r3 reconciled to `assets:read/write/delete:own` — no spec or seed row uses `update` or `create`.", "proposed_fix": "Rename throughout §5 P0.1 (endpoint table + seeding paragraph), §7 table, and P1.1/P1.3: `notifications:update:own` → `notifications:write:own`; `notification-prefs:update:own` → `notification-prefs:write:own`; `push-subscriptions:create:own` → `push-subscriptions:write:own` (keep `push-subscriptions:delete:own`). Seed the renamed six codes to the `user` role as already specified."}, {"file": "SPEC-04-notification-module.md", "severity": "major", "category": "unresolved-decision", "section": "§5 P0.4 dependency note vs §9 timeline vs §10", "summary": "P0.4 leaves its only hard dependency as an undecided either/or (\"either gate this item on SPEC-01 P1.2 or fold the one-line emit into this work item\"), yet §9 phase 4 schedules the consumer unconditionally and §10 does not carry the decision — an implementer starting phase 4 with SPEC-01 P0-only landed must guess.", "evidence": "SPEC-04:126: \"the emit side is SPEC-01 P1.2 — a nice-to-have that may not ship with SPEC-01's P0. If SPEC-01 lands P0-only there is nothing to consume; either gate this item on SPEC-01 P1.2 or fold the one-line emit into this work item\". SPEC-04:235 (§9 phase 4): \"`media:asset_ready` consumer + wire into `cmd/worker` (½ day)\" — no conditional. §10 (SPEC-04:240-246) has no entry for it. SPEC-01:256-264 confirms P1.2 is \"nice to have\" with \"no consumer required to ship\".", "proposed_fix": "Resolve the either/or in P0.4 and mirror it in §9 phase 4, e.g.: \"Decided: P0.4 is not gated. If SPEC-01 P1.2 has not landed when phase 4 starts, this work item includes the one-line `platform/events.Publish(\\\"media:asset_ready\\\", …)` call in media's ready-transition (coordinated with the media owner — it is their event name); the consumer never ships without a producer.\" Alternatively demote P0.4 to \"gated on SPEC-01 P1.2\" explicitly — but pick one."}, {"file": "SPEC-04-notification-module.md", "severity": "minor", "category": "missing-registration", "section": "§5 P0.4 + §7 task inventory", "summary": "The consumer task type P0.4 requires (\"notify handles its own consumer task type\") is never named, and is absent from both §7's owned-task list and the events.md Tasks table — despite §7 declaring events.md registration part of definition-of-done.", "evidence": "SPEC-04:124: \"subscription goes through the `platform/events` fan-out … notify handles its own consumer task type\" — no name given. SPEC-04:222 lists only `notify:dispatch`, `notify:email`, `notify:web_push`, `notify:purge_old` and says the registry \"makes registration part of definition-of-done\". docs/reference/events.md:74 names the mapping only as a prose example (\"`media:asset_ready → notify:on_asset_ready`\"); its Tasks table (events.md:36-50) has no `notify:on_asset_ready` row.", "proposed_fix": "In P0.4, name the consumer task explicitly (\"notify registers `notify:on_asset_ready`; the `cmd/worker` subscription table maps `media:asset_ready → notify:on_asset_ready`, per events.md Delivery mechanics; the handler builds the intent and runs the P0.2 dispatch logic\"), add `notify:on_asset_ready` to §7's owned-task list, and add the row to events.md's Tasks table as part of DoD."}, {"file": "SPEC-04-notification-module.md", "severity": "minor", "category": "ac-contradiction", "section": "§5 P0.4 acceptance criteria vs §8 success metrics", "summary": "P0.4's AC promises the notification \"within a few seconds\" of the event, but §8 explicitly states the P0 (poll-only) visibility target is ≤60 s and that \"a 60 s poll cannot honestly claim 10 s\" — a tester applying the AC at P0 fails a correct implementation.", "evidence": "SPEC-04:131: \"Given a video that reaches `ready`, when the event fires, then the owner has a new in-app notification linking to the asset within a few seconds.\" vs SPEC-04:227: \"< 10 s p95 with P1.2 SSE; the P0 (poll-only) target is visible by the next poll/focus refetch (≤ 60 s, P0.5) — a 60 s poll cannot honestly claim 10 s.\"", "proposed_fix": "Reword the AC to separate store from visibility: \"Given a video that reaches `ready`, when the event fires, then a `notifications` row for the owner exists within a few seconds (queue latency), and it is visible in the bell by the next poll/focus refetch (P0.5) — or < 10 s once P1.2 SSE lands (§8).\""}, {"file": "SPEC-04-notification-module.md", "severity": "minor", "category": "missing-mechanism", "section": "§5 P1.4 vs P0.2 step 2 vs §6", "summary": "P1.4 declares `account.security_alert` \"email + in-app, not mutable off\", but the only channel-forcing mechanism the spec defines is the intent `channels` union — and P1.4 never states the emitting intent carries one; the §6 prefs schema cannot make the per-channel booleans immutable, so a user with `{email:false, in_app:false}` for this type would receive nothing.", "evidence": "SPEC-04:152: \"account emits on `account.refresh.reuse_detected` → `type:\\\"account.security_alert\\\"` (email + in-app, not mutable off)\". P0.2 step 2 (SPEC-04:81) only says non-mutable types \"ignore `muted`\" — the channel union still comes from \"the stored preference for `type` … unioned with the intent's `channels` override\". §6 (SPEC-04:179-187) has plain boolean columns with no immutability.", "proposed_fix": "Append to P1.4: \"The emitting intent carries `channels:[\\\"email\\\",\\\"in_app\\\"]` — the P0.2 union is what makes the type undisableable (same pattern as password reset); 'not mutable off' is enforced by the override + the muted-ignore rule, not by the prefs schema.\""}, {"file": "SPEC-04-notification-module.md", "severity": "minor", "category": "dangling-reference", "section": "§1 problem statement", "summary": "§1 cites \"§2 of the gap audit's priorities\" although the header itself records that the standalone gap-audit file was never committed and its content was folded into backlog.md — the reference points at a document that does not exist.", "evidence": "SPEC-04:18: \"It is the backbone that unblocks §2 of the gap audit's priorities.\" vs SPEC-04:4: \"the standalone `gap-audit-2026-07.md` file was never committed; link fixed 2026-07-10\". backlog.md's §2 is \"Media — slice built, gaps\" (backlog.md:37), not a notification-adjacent priority list, so the reader cannot resolve it there either.", "proposed_fix": "Replace with a resolvable citation, e.g.: \"It is the backbone that unblocks the notification-dependent items now tracked in backlog §1 (password reset), §3 (social-surface delivery), and §5 (the `notify:*` module itself).\""}, {"file": "SPEC-04-notification-module.md", "severity": "minor", "category": "underspecified-api", "section": "§5 P0.1 / §7 API summary", "summary": "The default of the `?status=` filter on GET /me/notifications is unspecified — §5 offers `unread|all`, §7 shows `?status=&cursor=`, and no AC covers the parameter being absent, so implementations may disagree on what the bell's initial fetch returns.", "evidence": "SPEC-04:55: \"`?status=unread\\|all&cursor=` ; returns items + `unread_count`\"; SPEC-04:209: \"`?status=&cursor=`; `{items, unread_count, next_cursor}`\"; the ACs (SPEC-04:60-65) exercise only `?status=unread` and pagination, never the no-param case. P0.5 (SPEC-04:138) fetches `useQuery([\"notifications\"])` without saying which status it requests.", "proposed_fix": "State the default in the P0.1 table note and §7: \"`status` defaults to `all` (the bell dropdown shows read + unread; the badge uses `unread_count`)\" — and add one AC: \"Given no `status` param, the response contains both read and unread items ordered `created_at DESC, id DESC`.\""}, {"file": "SPEC-03-finance-ledger.md", "severity": "major", "category": "unimplementable-ambiguous", "section": "P0.4 Categories / §7 API", "summary": "The claimed 2-level enforcement ('parent_id must reference a top-level category') is insufficient because PATCH /bank/categories/{id} exists and parent_id mutability is undefined — re-parenting a category that already has children passes the stated check yet creates a 3-level tree, silently breaking P0.5's direct-children budget roll-up.", "evidence": "SPEC-03:172-174 'parent_id must reference a **top-level** category (parent_id IS NULL — this is what enforces \"2 levels max\")' vs SPEC-03:460 'PATCH/DELETE /api/v1/bank/categories/{id}'. Only kind is declared immutable (SPEC-03:178 'kind is immutable after creation'), implying name and parent_id are patchable. Setting a parent on a node that has children satisfies 'parent references a top-level category' while its existing children land at depth 3; P0.5 (SPEC-03:214 'including its children', SPEC-03:179 '\"Children\" always means direct children') then under-counts the grandchild's spend.", "proposed_fix": "Add to P0.4 hierarchy invariants: 'parent_id is mutable via PATCH, but a category that has children cannot be assigned a parent (422 bank/invalid-category-parent) — together with the top-level rule this is what actually enforces 2 levels max; re-parenting also re-runs the same-kind and own-or-seed checks.' (Alternatively declare parent_id immutable after creation alongside kind.)"}, {"file": "SPEC-03-finance-ledger.md", "severity": "minor", "category": "internal-contradiction", "section": "P0.8 RBAC acceptance criteria vs P0.4", "summary": "P0.8's seed-immutability AC carves out superadmin ('any non-superadmin mutation ... 404'), contradicting P0.4's absolute 'Seeds are not deletable' (called load-bearing) and P0.8's own 'category mutations stay strictly owner-scoped'; no :any mutation surface even exists in §7, so the carve-out is unimplementable as written.", "evidence": "SPEC-03:319-321 'any non-superadmin mutation matches zero rows → 404' vs SPEC-03:182-184 'Seeds are not deletable ... Load-bearing, not just tidy — a seed delete would cascade every user's budgets on it' and SPEC-03:298-299 'category **mutations** stay strictly owner-scoped'. §7 (SPEC-03:451-462) lists only :own permissions — there is no endpoint through which a superadmin mutation of a seed could succeed.", "proposed_fix": "In the P0.8 AC, delete 'non-superadmin': 'Given a seed category (user_id NULL), then reads include it for every user, and any mutation attempt via the shipped endpoints matches zero rows → 404 (what makes seeds immutable, P0.4 — no :any mutation surface exists at v1, so this holds for superadmin too).'"}, {"file": "SPEC-03-finance-ledger.md", "severity": "minor", "category": "unimplementable-ambiguous", "section": "P0.5 Monthly budgets", "summary": "Budgets on income-kind categories are representable (the PUT write semantics only require own-or-seed resolution) but meaningless — spent is defined as 'Σ expense debits', so an income-category budget renders a permanent 0% bar; accept-or-reject is undefined and an implementer must guess.", "evidence": "SPEC-03:214 'Spent = Σ expense debits in the month for the category' and SPEC-03:223-224 'Category must resolve within the caller's visible set (own or seed) per the P0.2/P0.4 convention' — no kind restriction, while every other category-referencing write (P0.2 direction match, P0.4 reassign_to 'be of the same kind') carries one.", "proposed_fix": "Add to the P0.5 write semantics: 'The category must be expense-kind; a PUT naming an income-kind category is 422 bank/category-kind-mismatch (spent is defined only over expense debits).'"}, {"file": "SPEC-03-finance-ledger.md", "severity": "minor", "category": "wrong-cross-reference", "section": "§3 Non-goals", "summary": "The non-goal 'Debts, loans, investments, savings goals' cites feature-inventory.md §8.3–8.5, but savings goals is §8.6 — the cited range omits it.", "evidence": "SPEC-03:42-43 'Debts, loans, investments, savings goals (feature-inventory.md §8.3–8.5)' vs feature-inventory.md:124-142 '### 8.3 Debts ... ### 8.4 Loans ... ### 8.5 Investments ... ### 8.6 Savings goals'.", "proposed_fix": "Change '(feature-inventory.md §8.3–8.5)' to '(feature-inventory.md §8.3–8.6)'."}, {"file": "SPEC-03-finance-ledger.md", "severity": "minor", "category": "wrong-cross-reference", "section": "Header (Refs)", "summary": "The header says the spec 'implements a subset of §8.1–8.2', but P0.5 monthly budgets implement feature-inventory §8.7 (Budgets), which the cited range excludes.", "evidence": "SPEC-03:4 'feature-inventory.md §8 (implements a subset of §8.1–8.2)' vs feature-inventory.md:147 '### 8.7 Budgets — Per-category caps for a period'. SPEC-03 P0.5 (line 212) ships monthly per-category budgets.", "proposed_fix": "Change the header ref to 'feature-inventory.md §8 (implements a subset of §8.1–8.2 plus monthly budgets from §8.7)'. (The upstream brief carries the same stale range; fixing the spec is what matters for implementers.)"}, {"file": "SPEC-03-finance-ledger.md", "severity": "minor", "category": "wrong-cross-reference", "section": "P0.7 Events", "summary": "P0.7 justifies the platform/events helper by claiming the bank events 'already have a registered second consumer (SPEC-06's stream)', but events.md registers the stream as their only (first) consumer — and the same paragraph says 'No consumer required to ship', an internal tension.", "evidence": "SPEC-03:285-286 'these events already have a registered second consumer (SPEC-06's stream)' vs events.md:24-26 where the Consumers column for bank:transaction_created/updated/deleted lists only 'stream (SPEC-06 P0.1)'. The 'second consumer' phrasing belongs to events.md's media:asset_ready example (events.md:68 'the moment an event gains a second consumer (SPEC-06's stream joins SPEC-04's notify)').", "proposed_fix": "Replace with: 'No consumer required to ship, but these events already have a registered first consumer (SPEC-06's stream) — publish via the platform/events helper (events.md \"Delivery mechanics\") so a second consumer later is a wiring change.'"}, {"file": "SPEC-03-finance-ledger.md", "severity": "minor", "category": "brief-coverage", "section": "P0.3 Transfers", "summary": "The brief's transfer requirement 'Editing/deleting one leg edits/deletes the pair atomically' is silently inverted: the spec returns 409 bank/is-transfer-leg on leg-level PATCH/DELETE and routes mutations through a dedicated transfer endpoint, without noting it supersedes the brief's leg-cascade behavior.", "evidence": "briefs/03-finance-ledger.md:64 'Editing/deleting one leg edits/deletes the pair atomically.' vs SPEC-03:128-131 'Legs are **not** independently editable ... a PATCH/DELETE on a leg's transaction id returns 409 bank/is-transfer-leg pointing at the transfer endpoint.' The atomicity intent is preserved but the API behavior an implementer of the brief would expect (cascade) is replaced (reject), with no supersession note.", "proposed_fix": "Add one clause to P0.3: 'This deliberately supersedes the brief's \"editing one leg edits the pair\" — the atomicity guarantee moves to the transfer endpoint; leg-level mutation is rejected rather than cascaded, so a client can never half-express a transfer edit.'"}, {"file": "SPEC-06-life-stream-home.md", "severity": "major", "summary": "P1.6 backfill seeds stream_items from ALL existing media assets, silently bypassing the P0.1 origin='import' zip-import flood guard — and the guard is unimplementable at backfill time because SPEC-01 persists no origin column (origin is computed only at event-emit time).", "evidence": "SPEC-06-life-stream-home.md:193-197: \"P1.6 Backfill task `journal:backfill_stream` ... seeds `stream_items` from existing **media assets'** upload dates **via `mediaapi` listing**\" — with no import exclusion. This contradicts SPEC-06-life-stream-home.md:83 \"insert; **skip `origin='import'`** (zip-import flood guard)\" and the AC at :119 \"Given a `media:asset_ready` with `origin='import'`, then no stream item.\" The risk is real, not theoretical: specs/README.md:84-86 sequences SPEC-06 last, after SPEC-02's zip import (≤300 assets per chapter, per events.md:20) can have created page assets. And SPEC-01-media-image-pipeline.md:259-261 defines origin only on the event (\"`origin` is `'upload'` for user uploads, `'import'` for batch-created assets\"); SPEC-01 §6 adds no `origin` column to `assets`, so a plain `mediaapi` listing has nothing to filter on. Also, P1.6 never states the event_type the seeded rows use, yet claims \"Idempotent via the same unique constraint\" (:197) — dedup against live `media:asset_ready` inserts only works if the backfill writes the identical (source_module, event_type, ref_id) key.", "section": "§5 P1.6 (vs P0.1 flood guard and §6)", "category": "internal-contradiction", "proposed_fix": "Extend P1.6: \"Seeded rows use `source_module='media'`, `event_type='media:asset_ready'`, `ref_id=asset_id` — identical to the live consumer's key, so the unique constraint dedups against real events. The backfill applies the same exclusion as the live consumer: batch-imported assets (SPEC-02 zip import) are skipped. Since SPEC-01 does not persist `origin` on `assets`, the `mediaapi` listing used here must expose an import/batch discriminator (coordinate with SPEC-01/SPEC-02 — e.g. persist `origin` or filter out assets referenced as comic pages); until it does, the backfill is restricted to instances with no comic imports.\""}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "summary": "The stream_items values for journal-sourced rows (event_type, payload) are never specified, though three places must write/match the same key: the transactional path P0.1(a), the migration backfill INSERT…SELECT, and the P0.2 read discrimination/join.", "evidence": "SPEC-06-life-stream-home.md:67-69 says only \"create inserts the stream row\"; :103-107 says the migration \"seeds rows for **all existing `journal_entries`** (`INSERT … SELECT`)\"; §6 (:218-221) makes `event_type text NOT NULL` part of `UNIQUE (source_module, event_type, ref_id)` and its comment lists only system examples (\"registry name, e.g. 'media:asset_ready'\"). Nothing states what `event_type` or `payload` a journal row carries, so the service code and the migration SQL could diverge and break the unique-key contract and the P0.2 join (:130-132 \"joined from `journal_entries`\").", "section": "§5 P0.1(a) + backfill / §6", "category": "ambiguity", "proposed_fix": "Add one sentence to P0.1(a) and reference it from the backfill paragraph: \"Journal projection rows are written as `source_module='journal'`, `event_type='journal:entry_created'` (the registry name, uniform even though no bus delivery is involved), `ref_id = entry id`, `payload = '{}'` — journal items render by joining `journal_entries` (P0.2), never from payload. The `000N_journal_stream_items` backfill INSERT…SELECT writes the same values.\""}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "summary": "Handler behavior for `bank:transaction_updated` arriving when no matching row exists (created-task retry reordered after the update) is undefined — as written, the update no-ops and the later created retry inserts the stale pre-correction payload, which then renders wrong indefinitely, contradicting the row's own stated intent.", "evidence": "SPEC-06-life-stream-home.md:87: \"`bank:transaction_updated` ... update the matching row's `payload` + `occurred_at` (a corrected amount must not render wrong forever)\". The spec's residual-risk note (:98-101) covers only the create-after-delete reorder (\"a `*_created` retry processed *after* the corresponding `*_deleted` resurrects an item\") and calls it \"self-correcting on the next delete\" — but the create-after-update reorder is neither covered nor self-correcting: the stale amount persists until an unrelated future edit.", "section": "§5 P0.1(b) consumer table + residual-risk note", "category": "undefined-edge-case", "proposed_fix": "Change the `bank:transaction_updated` handler action to an upsert: \"INSERT ... ON CONFLICT (source_module, event_type, ref_id) DO UPDATE SET payload, occurred_at — writing the row under the created-event key (`event_type='bank:transaction_created'`) when absent. A reordered `*_created` retry then hits DO NOTHING and the corrected payload wins regardless of delivery order.\" Alternatively, extend the residual-risk paragraph to explicitly accept update-before-create alongside create-after-delete."}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "summary": "P0.3's optimistic-insert wording (\"prepends\"/\"appears at the stream top\") contradicts SPEC-05's composer contract, where a backdated post must appear at its occurred_at position — top only when now-dated.", "evidence": "SPEC-06-life-stream-home.md:156-157 \"a successful post optimistically prepends to the stream query\" and AC :160-161 \"Given a new journal post, then it appears at the stream top optimistically\" vs SPEC-05-journal.md:132-134 (composer \"exposes an optional **date control** (`occurred_at`...)\") and SPEC-05-journal.md:144-145 AC \"the entry appears at its `occurred_at` position (top, when now-dated)\". SPEC-06 P0.3 reuses that same composer (\"with the SPEC-05 composer on top\"), so a literal prepend misplaces backdated posts.", "section": "§5 P0.3", "category": "cross-spec-contradiction", "proposed_fix": "Reword P0.3 body to \"a successful post is optimistically inserted at its `occurred_at` position in the stream query\" and the AC to \"Given a new journal post, then it appears at its `occurred_at` position (top, when now-dated) optimistically and survives an immediate refetch — guaranteed, not racy, because the projection row is written in the create transaction (P0.1(a)).\""}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "summary": "The P0.2 title/href render-mapping — including its load-bearing fallback (\"an event type without a mapping renders a generic card, never an error\") — has no acceptance criterion; P0.2's ACs cover only ordering and user scoping.", "evidence": "SPEC-06-life-stream-home.md:135-144 defines the per-event-type render mapping and the generic-card fallback as P0 behavior; the P0.2 ACs (:146-149) test only \"one stable merged order with correct cursor traversal\" and \"user A's stream never contains [user B's items]\" — nothing verifies title/href synthesis or the no-mapping fallback, even though P0.1 has the parallel ingest-side AC (:120-121, unknown event type skipped with a log line).", "section": "§5 P0.2 acceptance criteria", "category": "ac-coverage", "proposed_fix": "Add two ACs to P0.2: \"Given stored system items of each mapped event type, then the response carries the synthesized `title` and `href` per the render mapping (e.g. `media:asset_ready` → '<title> is ready', `/library/media#id`).\" and \"Given a stored system item whose `event_type` has no render mapping, then `GET /stream` returns 200 with a generic card for it (no `href`), never a 5xx.\""}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "summary": "The header dependency line lists SPEC-04 under \"system events attach as ... land\" although SPEC-04 produces no stream event (it is a widget/consumer dependency), and omits three of the five actual event producers (SPEC-02 P1.9, SPEC-07 P1.5, SPEC-08 P0.4) that the P0.1 table depends on.", "evidence": "SPEC-06-life-stream-home.md:4: \"system events attach as SPEC-01 P1.2 / SPEC-03 P0.7 / SPEC-04 land\" — but the P0.1 consumer table (:83-90) ingests events from SPEC-01 P1.2/P0.3, SPEC-07 P1.5, SPEC-03 P0.7, SPEC-02 P1.9, and SPEC-08 P0.4; SPEC-04 appears nowhere in that table (it supplies only the Activity-feed widget endpoint, :176). events.md:20-29 confirms SPEC-04's notify is a sibling consumer, not a producer.", "section": "Header (Depends on)", "category": "wrong-cross-reference", "proposed_fix": "Replace with: \"system events attach as their producers land (SPEC-01 P1.2/P0.3, SPEC-02 P1.9, SPEC-03 P0.7, SPEC-07 P1.5, SPEC-08 P0.4); the widget rail additionally consumes SPEC-04's `GET /me/notifications` — **every widget and consumer degrades to an empty state**, none is a blocker\"."}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "major", "category": "rbac-enforcement-contradiction", "section": "§5 P0.3 Delete asset + §7 API summary", "summary": "DELETE /assets/{id} is specced as RequirePermission(`assets:delete:own`) while simultaneously claiming `assets:delete:any` covers admin — but the real matcher never lets an `:any` grant satisfy an `:own` requirement, so admin's 0003 grant is inert and admin/moderation delete is impossible as written (even superadmin `*` passes the code check only to fail the handler's step-1 ownership check).", "evidence": "SPEC-01-media-image-pipeline.md:169-172: \"`DELETE /api/v1/assets/{id}` — permission `assets:delete:own` *(rev 3: the 0003 catalog already seeds this exact code to `creator`; `assets:delete:any` covers admin ...)*\" and :329 (§7 table row \"DELETE | `/api/v1/assets/{id}` | `assets:delete:own`\"); P0.3 behavior :176 \"(1) authorize ownership\". Conflicts with backend/internal/modules/account/rbac/permission.go:134-147 (granted scope \"any\" matches required \"\" or \"any\" only — never \"own\") and with the codebase's own canonical pattern for this exact endpoint, backend/internal/modules/account/rbac/engine.go:61-62: \"This is the canonical pattern for endpoints like DELETE /assets/{id}: owners can delete their own; admins (with assets:delete:any) can delete any\" via middleware/rbac.go:48-60 RequireOwnerOrPermission. README.md:47-48 binds specs to RequirePermission enforcement, so an implementer wiring RequirePermission(\"assets:delete:own\") produces a system where nobody but the owner can ever delete, contradicting the spec's admin claim and the AC at :197-198 (\"without wildcard perms, then 403\" implies elevated perms should pass).", "proposed_fix": "In §7 change the DELETE row's Permission cell to: \"owner, or `assets:delete:any` (`RequireOwnerOrPermission`)\". In P0.3 replace the parenthetical with: \"*(rev 4: enforced via `RequireOwnerOrPermission(engine, \\\"assets:delete:any\\\", extractAssetOwner)` — the canonical owner-or-elevated pattern in account/middleware/rbac.go, whose doc names this exact endpoint. A plain `RequirePermission(\\\"assets:delete:own\\\")` would 403 admin's 0003-seeded `assets:delete:any` grant, because the matcher never lets an `:any` grant satisfy an `:own` requirement. `assets:delete:own` remains the 0003 catalog entry documenting the owner-side capability; the middleware's owner branch is what actually admits owners.)*\""}, {"file": "SPEC-02-comic-vertical.md", "severity": "major", "category": "rbac-enforcement-contradiction", "section": "§5 P0.2 Publish flow + RBAC + §7 API summary", "summary": "P0.2 mandates \"all via RequirePermission\" with `:own` codes on every mutation endpoint, which makes the two moderation grants the same section seeds (`comics:write:any`, `comics:delete:any`) satisfy no endpoint at all — moderation of another user's comic is impossible below superadmin — and the acceptance criterion tests an admin holding `comics:*`, a grant nothing seeds; there is also no elevated publish/unpublish code, so a moderator cannot unpublish an offensive comic.", "evidence": "SPEC-02-comic-vertical.md:81 \"Permissions (all via `RequirePermission`; wildcard `comics:*` covers every scope)\"; :88-93 table maps every mutation to `comics:write:own`/`comics:publish:own`; :95-99 \"`comics:delete:any` + `comics:write:any` → admin-tier for moderation\"; :110-111 AC \"Given an admin with `comics:*`, then all scopes pass\"; §7 :309-315 lists `comics:write:own` on PATCH/DELETE/chapters/pages rows. Under backend/internal/modules/account/rbac/permission.go:134-147 a `comics:write:any` grant never matches a required `comics:write:own` (gs==\"any\" matches rs \"\" or \"any\" only), so the seeded `:any` codes gate nothing — dead rows in the catalog. The owner-or-elevated composition exists as middleware (account/middleware/rbac.go:48-60 RequireOwnerOrPermission).", "proposed_fix": "Rework P0.2 and §7 to the owner-or-elevated pattern: (1) POST `/comics`, GET `/comics/mine` stay `RequirePermission(\"comics:write:own\")`. (2) Every mutation on an existing comic/chapter/page (PATCH/DELETE comics, chapters CRUD, pages CRUD, :order, :import-zip) becomes \"owner, or `comics:write:any`\" via `RequireOwnerOrPermission(engine, \"comics:write:any\", extractComicOwner)`; DELETE `/comics/{id}` uses elevated `comics:delete:any`; `{status}` changes use elevated `comics:publish:any`. (3) Seeding paragraph: \"`comics:read` → `user`; `comics:write:own` + `comics:publish:own` → `creator`; `comics:write:any` + `comics:publish:any` → `editor`; `comics:delete:any` → `admin` (matching 0003's movies precedent — editor writes/publishes any, admin deletes any)\" — adding the previously missing `comics:publish:any` row. (4) Change the AC to \"Given an editor with `comics:write:any`, then edits to another creator's comic pass; given an admin with `comics:delete:any`, DELETE passes; given a test-granted `comics:*`, all scopes pass (regression test for the wildcard-action rule)\"."}, {"file": "SPEC-04-notification-module.md", "severity": "major", "category": "naming-coherence", "section": "§5 P0.1 (endpoint table + permission seeding) + §7 API summary", "summary": "SPEC-04's permission codes use `update` and `create` action verbs (`notifications:update:own`, `notification-prefs:update:own`, `push-subscriptions:create:own`), contradicting the binding README canon (action ∈ read|write|delete plus sparing domain verbs) and the explicit reconciliations in SPEC-05/08/09 that rejected exactly this verb style — leaving the catalog with two competing action vocabularies an implementer must choose between.", "evidence": "SPEC-04-notification-module.md:56-57, 70-73 (\"seeds `notifications:read:own`, `notifications:update:own`, `notification-prefs:read:own`, `notification-prefs:update:own`, `push-subscriptions:create:own`, `push-subscriptions:delete:own`\"), :210-213 (§7 rows repeat them). Conflicts with docs/product/specs/README.md:52-54 \"action ∈ `read | write | delete` plus sparing domain verbs (`publish`)\" (binding convention), SPEC-05-journal.md:210-213 \"`write` covers create + update, matching the 0003 catalog — the earlier `journal:create`/`journal:update:own` split added a verb style the catalog doesn't use *(reconciled 2026-07-10)*\", SPEC-08-people-registry.md:66-67 \"canonical scheme: `write` covers create + update\", and SPEC-09-platform-ops.md:174-175 \"`takeout:write:own` — canonical verb\". 0003_account_rbac.up.sql:72-119 contains no `update`/`create` action anywhere.", "proposed_fix": "Reconcile SPEC-04 to the canonical verb set (one scheme across all ten specs — resource kebab-compound nouns, actions read|write|delete [+publish], scope own|any): replace `notifications:update:own` → `notifications:write:own` (POST /me/notifications/{id}/read and /read-all rows in the P0.1 table and §7); `notification-prefs:read/update:own` → `notification-prefs:read/write:own` (P1.3 row); `push-subscriptions:create:own` → `push-subscriptions:write:own` (keep `push-subscriptions:delete:own`). Update the P0.1 seeding paragraph to the six corrected codes: `notifications:read:own`, `notifications:write:own`, `notification-prefs:read:own`, `notification-prefs:write:own`, `push-subscriptions:write:own`, `push-subscriptions:delete:own` — all granted to the base `user` role, unchanged mechanics. Add a one-line 2026-07 reconciliation note mirroring SPEC-05 §7's."}, {"file": "MULTIPLE", "severity": "minor", "category": "incorrect-failure-mode", "section": "SPEC-01 §7 note; SPEC-03 §5 P0.8; SPEC-04 §7 note", "summary": "Three specs claim a malformed (4-segment) permission code \"would 403 everyone, superadmin included\" at runtime; through the canonical enforcement path the actual failure is a server-start panic — RequirePermission parses the required code with rbac.MustParse at middleware build time — so the runtime-403 description is only true for bare Set.AllowsCode checks, not for endpoints wired per the specs' own convention.", "evidence": "SPEC-01-media-image-pipeline.md:335-337 \"The earlier 4-segment `media:asset:*:own` drafts are rejected by `rbac.Parse`, whose fail-closed matcher would 403 everyone, superadmin included\"; SPEC-03-finance-ledger.md:300-302 \"wired as drafted, every bank endpoint would 403 everyone, superadmin included\"; SPEC-04-notification-module.md:220 \"a 4-segment module-prefixed code would 403 everyone — including a `*` superadmin\". Contradicted by backend/internal/modules/account/middleware/rbac.go:17-20 \"The required code is parsed once at middleware build time; a malformed code panics — surfacing a programmer error before the server starts\" (RequirePermission calls rbac.MustParse, permission.go:79-85), while the 403 behavior belongs to Set.AllowsCode (permission.go:189-197).", "proposed_fix": "In each of the three notes, replace the \"would 403 everyone, superadmin included\" clause with: \"is rejected by `rbac.Parse`: wired through `RequirePermission` it panics at server start (`MustParse` on the required code), and any dynamic `AllowsCode` check fails closed — returning false even for a `*` superadmin grant.\" The reconciled 3-segment codes and the conclusion are unchanged; only the described failure mode is corrected."}, {"file": "SPEC-01-media-image-pipeline.md", "severity": "major", "category": "event-payload-persistence", "section": "P1.2 / §6 data model", "summary": "The `origin` field of `media:asset_ready` — the load-bearing zip-import flood guard for SPEC-04's bell and SPEC-06's stream — has no persistence mechanism: no column stores it and the worker task payload cannot carry it, so the emit cannot know the value.", "evidence": "SPEC-01:260–262 requires \"`origin` is `'upload'` for user uploads, `'import'` for batch-created assets (SPEC-02 P1.7 zip import), so consumers can suppress bulk floods\" and the event fires \"whenever any asset reaches `ready`\" (SPEC-01:258) — i.e. worker-side, at the end of `media:process_image`, whose payload is only `{asset_id}` (SPEC-01:93, events.md:39). But SPEC-01 §6's migration (SPEC-01:308–315) adds only `title` and `original_filename` — no `origin` column — and SPEC-02:212–214 says assets are \"created … via `mediaapi` (batch, marked `origin='import'`…)\" without saying where that mark lives. Both consumers key on it: SPEC-04:124 \"Events with `origin='import'` are skipped\", SPEC-06:83 \"skip `origin='import'`\", events.md:20. As specced, the emitter has no way to populate the field.", "proposed_fix": "In SPEC-01 §6, extend the rev-3 ALTER TABLE with: `ADD COLUMN origin text NOT NULL DEFAULT 'upload' CHECK (origin IN ('upload','import'))`. Add one sentence to P1.2: \"`origin` is read from `assets.origin`, set at row creation — `'upload'` by the upload-session endpoint (default), `'import'` by the `mediaapi` batch-create SPEC-02 P1.7 uses.\" Also state that `mediaapi` asset listings expose `origin` (SPEC-06 P1.6's backfill needs it — see the related SPEC-06 finding)."}, {"file": "MULTIPLE", "severity": "major", "category": "event-payload-contract", "section": "SPEC-03 P0.7 / SPEC-06 P0.1(b)+P0.2 / events.md", "summary": "The single collapsed transfer stream item stores whichever leg's event happened to be processed first (ON CONFLICT DO NOTHING), so its rendered direction/account is nondeterministic — and the payload carries no counterparty account, making SPEC-03's declared card copy ('moved 5M TCB→Momo') unrenderable from the stored payload.", "evidence": "SPEC-03:278–280: \"`transfer_id` … lets a consumer group one transfer's rows into a single story item (\\\"moved 5M TCB→Momo\\\", not two confusing entries)\". SPEC-03 P0.7 emits per leg (\"Emitted for transfer legs too\", SPEC-03:280) with payload `{transaction_id, user_id, account_id, amount, direction, category_id, occurred_at, is_transfer, transfer_id}` (SPEC-03:275–276, events.md:24) — one leg's `account_id`/`direction` only, no counterparty. SPEC-06:86 collapses both legs onto `ref_id = transfer_id` and SPEC-06:92 \"Inserts use ON CONFLICT (source_module, event_type, ref_id) DO NOTHING\" — so the surviving payload is the first-arriving leg (debit or credit, race-dependent), and SPEC-06:143 renders \"applied at read time from the stored payload\". Same nondeterminism on `bank:transaction_updated`: both legs' events overwrite the one row (SPEC-06:87), last writer wins.", "proposed_fix": "In SPEC-03 P0.7, add `counterparty_account_id` (nullable; on a transfer leg, the other leg's `account_id`; NULL otherwise, including the P1.13 fee row) to the `bank:transaction_created/updated/deleted` payload, and mirror it in events.md's payload sketch. In SPEC-06 P0.2, add a transfer render rule: \"for `is_transfer` payloads, normalize on direction — source account = the debit side (`account_id` when `direction='debit'`, else `counterparty_account_id`) — so either leg's stored payload renders the identical 'moved <amount> <source>→<dest>' card.\""}, {"file": "SPEC-04-notification-module.md", "severity": "major", "category": "event-redelivery-idempotency", "section": "P0.2 / §6 data model", "summary": "The notifications store has no idempotency mechanism under at-least-once delivery: an Asynq retry of `notify:dispatch` (crash after the row insert, before channel-task enqueue/ack) or SPEC-08's outbox re-publish inserts duplicate bell rows — directly contradicting SPEC-08's acceptance criterion that consumers see no duplicate item.", "evidence": "SPEC-08:151–152 mandates \"at-least-once delivery, with consumers idempotent by `notice_id` (SPEC-06 keys stream items on it)\" — naming a mechanism only for the stream — and its AC (SPEC-08:170–172) requires \"the next scan publishes exactly that notice … and consumers see no duplicate item\", while events.md:29 lists \"notify (SPEC-04)\" as a consumer. But SPEC-04's `notifications` DDL (SPEC-04:166–175) has no unique/dedup key, and the P0.2 handler (SPEC-04:82, step 3: \"insert a `notifications` row\") specs no redelivery protection — the only failure handling is `asynq.SkipRetry` for malformed intents (SPEC-04:84). Contrast SPEC-06:92, where \"idempotency under redelivery is structural\" via the unique key.", "proposed_fix": "In SPEC-04 §6, add `dedup_key text` (nullable) to `notifications` plus `CREATE UNIQUE INDEX ON notifications (user_id, type, dedup_key) WHERE dedup_key IS NOT NULL;`. In P0.2, extend `NotificationIntent` with optional `dedup_key` (event-derived natural id — e.g. `notice_id` for birthdays, `asset_id` for `media.asset_ready`), have the in-app insert use `ON CONFLICT DO NOTHING`, and skip channel fan-out when the row already exists. Add an AC: \"Given a redelivered dispatch intent carrying a dedup_key, then exactly one notifications row exists.\" Document that channel sends (email/push) remain at-least-once."}, {"file": "SPEC-07-continue-rail.md", "severity": "minor", "category": "event-payload-contract", "section": "P1.5", "summary": "`media:playback_completed` payload is `{asset_id, user_id}` only, but SPEC-06 envisions a \"watched X\" stream card and its resolved default is payload-only rendering — the title needed for the card is absent from the payload.", "evidence": "SPEC-07:133 and events.md:22 define the payload as `{asset_id, user_id}`. SPEC-06:85 speaks of \"a 'watched X' card\", SPEC-06:143 renders \"applied at read time from the stored payload\", and SPEC-06's open question resolves \"Start payload-only; add per-type fetchers only when a card demonstrably needs more\" (SPEC-06:272–273). events.md:86–87's own rule is \"payloads carry IDs + the minimum for a consumer to render\" — the minimum for 'watched X' includes the title, which every other renderable media event carries (`media:asset_ready` has `title`, events.md:20).", "proposed_fix": "In SPEC-07 P1.5 and events.md:22, extend the payload to `{asset_id, user_id, title}` (title falls back to `original_filename`, matching SPEC-01 P1.2's rule). Optionally add the mapping row to SPEC-06 P0.2's examples: `media:playback_completed → (\"Watched <title>\", /library/media#id)`."}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "category": "consumer-policy-consistency", "section": "P1.6", "summary": "The `journal:backfill_stream` task seeds stream items from ALL existing media assets with no `origin='import'` skip — one run reintroduces the up-to-300-items-per-imported-chapter flood the live consumer explicitly guards against.", "evidence": "SPEC-06:193–197: \"seeds `stream_items` from existing **media assets'** upload dates **via `mediaapi` listing** … Idempotent via the same unique constraint\" — no origin filter. The live path skips imports: SPEC-06:83 \"insert; **skip `origin='import'`** (zip-import flood guard)\", and events.md:20 states the field \"exists so a SPEC-02 zip import (≤300 assets) can't flood the bell/stream\". A backfill run after any zip import bypasses that guard entirely.", "proposed_fix": "Add to P1.6: \"skipping assets with `origin='import'` (the same flood-guard policy as P0.1's `media:asset_ready` consumer)\" — and note it requires the `mediaapi` listing to expose `origin` (see the SPEC-01 finding adding the column)."}, {"file": "SPEC-02-comic-vertical.md", "severity": "minor", "category": "event-lifecycle-asymmetry", "section": "P1.9 / §7 (chapter & comic DELETE)", "summary": "Comic is the only stream producer with no removal event: deleting a chapter or comic leaves a `comic:chapter_published` stream item whose href 404s forever, while media and bank deletions both remove their stream items.", "evidence": "SPEC-02 §7 offers `DELETE /api/v1/comics/{id}` and `PATCH/DELETE /api/v1/chapters/{id}` (SPEC-02:310–312), but P1.9 emits only `comic:chapter_published` (SPEC-02:225–226) and events.md:23 lists no comic deletion event. SPEC-06 itself treats dangling cards as a bug for media — SPEC-06:85: \"**delete ALL** `source_module='media'` rows with this `ref_id` … else a 'watched X' card dangles\" — and removes bank items on `bank:transaction_deleted` (SPEC-06:88). A deleted chapter's stream card (`ref_id = chapter_id`, SPEC-06:89) has no removal path and SPEC-06 §3 forbids editing/deleting system items in-stream (\"the fix for a wrong fact is in the owning module\", SPEC-06:46–47).", "proposed_fix": "Either (preferred) add to SPEC-02 P1.9: emit `comic:chapter_deleted {comic_id, chapter_id, owner_user_id}` on chapter delete and on comic delete (one per chapter), register it in events.md with consumer \"stream — delete the `(source_module='comic', ref_id=chapter_id)` item (SPEC-06 P0.1)\", and add the matching handler row to SPEC-06's P0.1 table; or, if dangling history cards are deliberately acceptable, say so explicitly in SPEC-06 §3 and require the render mapping to degrade a dead href gracefully."}, {"file": "SPEC-06-life-stream-home.md", "severity": "minor", "category": "event-durability", "section": "P0.1 known residual risk vs Goal 2", "summary": "Goal 2 claims events are captured \"durably from day one\", but every producer except SPEC-08 emits post-commit with no outbox — a producer crash between DB commit and Publish silently and permanently drops the stream item, a failure mode the residual-risk paragraph does not cover.", "evidence": "SPEC-06:32–33: \"A `stream_items` projection captures bus events **durably from day one**\"; the residual-risk paragraph (SPEC-06:98–101) covers only the create-retry-after-delete resurrect case. Producers emit at-most-once: SPEC-03:289–290 AC \"exactly one matching event is emitted, after commit\"; SPEC-05:106–107 \"Emit … after the create transaction commits\"; SPEC-07 P1.5 latches `completed_at` then publishes. Only SPEC-08 closes the hole — SPEC-08:145–152 built an outbox precisely because \"insert-then-emit was at-most-once\". SPEC-06 §8's durability metric only tests the consumer-down case (SPEC-06:248–249), not the emit-side crash window.", "proposed_fix": "Extend SPEC-06 P0.1's residual-risk paragraph: \"Second accepted residual: producers other than SPEC-08 emit post-commit without an outbox, so a producer crash between commit and Publish drops that item from the stream permanently (at-most-once emit). Accepted at v1; the same P2 reconcile sweep is the seam — it can diff `stream_items` against each producer's rows via their `api/` packages.\" Alternatively, if bank data is deemed too important to drop, require SPEC-03 to adopt SPEC-08's outbox pattern for its P0.7 emits."}]

// ---- Phase 1 (option B): reuse 12 cached finder result-sets from the 2026-07-11 01:27 run;
// only run the 6 cross-cutting lenses that were killed by the session limit. ----
const MISSING = new Set(['deps', 'reality', 'sql', 'api', 'frontend', 'critic'])
const finderThunks = []
for (const c of CROSS) {
  if (!MISSING.has(c.key)) continue
  finderThunks.push(() => agent(c.prompt, { label: 'x:' + c.key, phase: 'Review', schema: FIND_SCHEMA, effort: 'high' }))
}
const fresh = (await parallel(finderThunks)).filter(Boolean).flatMap((r) => r.findings || [])
const raw = PRIOR.concat(fresh)
log('Review complete: ' + PRIOR.length + ' cached + ' + fresh.length + ' fresh = ' + raw.length + ' raw findings')

// ---- Phase 2: dedup/merge ----
const dedupPrompt = RULES + [
  'You are the dedup/merge editor for ' + raw.length + ' raw findings from 18 independent reviewers (JSON below).',
  'Merge findings that describe the SAME underlying defect (even when filed under different files — set file to where the fix belongs, or MULTIPLE). Keep distinct defects separate — when unsure, keep separate.',
  'For merged items keep: the sharpest evidence, the most complete proposed_fix, the max severity.',
  'Drop only: pure style/lint complaints, and findings that merely restate a documented non-blocking open question without showing it is wrong.',
  'Do NOT invent new findings. Output every surviving finding, sorted critical → major → minor.',
  'RAW FINDINGS JSON:',
  JSON.stringify(raw),
].join('\n')
const merged = await agent(dedupPrompt, { label: 'dedup', phase: 'Merge', schema: FIND_SCHEMA, effort: 'high' })
const canon = (merged && merged.findings) || []
log('Merge complete: ' + canon.length + ' canonical findings')

// ---- Phase 3: adversarial verify, grouped by file ----
const byFile = {}
for (const f of canon) {
  const k = f.file || 'MULTIPLE'
  if (!byFile[k]) byFile[k] = []
  byFile[k].push(f)
}

const refuterPrompt = (file, json) => RULES + [
  'ADVERSARIAL VERIFICATION for findings on: ' + (file === 'MULTIPLE' ? 'multiple files under ' + S + '/' : S + '/' + file),
  'Default stance: each finding is WRONG until you re-verify it against the actual files. Re-read the cited files yourself — never trust the quoted evidence.',
  "For each indexed finding return verdict: 'confirmed' (evidence checks out, severity apt) | 'downgraded' (real but overstated or partially wrong — explain what part survives) | 'refuted' (not a real defect — quote the source text that disproves it).",
  'Also refute findings that merely restate a documented, deliberate decision that has its rationale in place.',
  "IMPORTANT — the spec files were REVISED on 2026-07-10 AFTER these findings were captured; many defects have since been fixed in place (look for '(2026-07-10)' / 'rev 3' annotations). If the current file no longer exhibits the defect, return 'refuted' with reasoning beginning 'FIXED:' — that counts as resolved, not as a false positive. Only 'confirmed'/'downgraded' verdicts represent defects still open in the CURRENT text.",
  'FINDINGS JSON:',
  json,
].join('\n')

const fixAuditPrompt = (file, json) => RULES + [
  'FIX AUDIT for findings on: ' + (file === 'MULTIPLE' ? 'multiple files' : S + '/' + file),
  'Assume each defect below was real when captured. The spec files were REVISED on 2026-07-10 after capture: first check whether the current file already resolves the defect — if yes, judge the APPLIED fix (the current text) instead of the proposed one and return verdict for it; if the applied fix is sound, return \'refuted\' with reasoning beginning \'FIXED:\'. Otherwise judge the proposed_fix: would applying it fully resolve the defect without contradicting the binding conventions (' + SRC.readme + '), the other specs, or the code reality?',
  "verdict: 'confirmed' (fix right as written) | 'downgraded' (fix incomplete/needs adjustment) | 'refuted' (fix wrong, or already correctly fixed in the current text — prefix 'FIXED:' for the latter). Whenever not confirmed, ALWAYS provide revised_fix with the corrected concrete fix (empty if FIXED).",
  'FINDINGS JSON:',
  json,
].join('\n')

const verified = await parallel(Object.entries(byFile).map(([file, fs]) => async () => {
  const json = JSON.stringify(fs.map((f, j) => ({ index: j, ...f })))
  const pair = await parallel([
    () => agent(refuterPrompt(file, json), { label: 'refute:' + file.replace('.md', '').slice(0, 18), phase: 'Verify', schema: VERDICTS_SCHEMA, effort: 'high' }),
    () => agent(fixAuditPrompt(file, json), { label: 'fixaudit:' + file.replace('.md', '').slice(0, 16), phase: 'Verify', schema: VERDICTS_SCHEMA, effort: 'medium' }),
  ])
  const ref = pair[0], fix = pair[1]
  return fs.map((f, j) => ({
    ...f,
    refuter: (ref && ref.verdicts && ref.verdicts.find((v) => v.index === j)) || null,
    fix_audit: (fix && fix.verdicts && fix.verdicts.find((v) => v.index === j)) || null,
  }))
}))

const flat = verified.filter(Boolean).flat()
const confirmed = flat.filter((f) => f.refuter && f.refuter.verdict !== 'refuted')
const refuted = flat.filter((f) => !f.refuter || f.refuter.verdict === 'refuted')
log('Verify complete: ' + confirmed.length + ' confirmed, ' + refuted.length + ' refuted')

return {
  counts: { raw: raw.length, canonical: canon.length, confirmed: confirmed.length, refuted: refuted.length },
  confirmed: confirmed,
  refuted: refuted.map((f) => ({ file: f.file, severity: f.severity, summary: f.summary, why: (f.refuter && f.refuter.reasoning) || 'no verdict returned' })),
}